static Object metgetPricingAttributeAttributeAsObject(
    GUPIPricingAttribute _pricingAttr,
    IdentifierName _attributeAsObjectName)
{
    // Only use this method on small batch of pricing attribute (e.g. a set of attribute fixed source level)
    ClassId attrClassId = classIdGet(_pricingAttr);
    DictClass dictClass;
    METGUPPricingAttributeEcoResAttribute  metGUPPricingAttributeEcoResAttribute;
    metGUPPricingAttributeEcoResAttribute.getEcoResAttributeProviderId();

    if (attrClassId == classNum(METGUPPricingAttributeEcoResAttribute))
    {
        if (_attributeAsObjectName == attributeStr(GUPPricingAttributeFieldsDiscoveryAttribute))
        {
            return null;
        }

        attrClassId = (_pricingAttr as METGUPPricingAttributeEcoResAttribute).getEcoResAttributeProviderId();
    }

    dictClass = new DictClass(attrClassId);
    Object attributeAsObject = dictClass.getAttribute(_attributeAsObjectName);

    if (!attributeAsObject)
    {
        throw error(strFmt("@GlobalUnifiedPricing:GUPPricingAttributeRepository_CheckAttributeAsObject", _attributeAsObjectName, classId2Name(attrClassId)));
    }

    return attributeAsObject;
}
